+// gates/config.mjs — load + normalize .claude/house-standard.config.json.
+import { readFileSync, existsSync } from 'node:fs';
+import { join } from 'node:path';
+
+export function normalizeConfig(raw) {
+  const paths = raw.paths || {};
+  const g = raw.gates || {};
+  const out = {
+    paths: { backend: paths.backend || 'backend', frontend: paths.frontend || 'frontend' },
+    gates: {
+      lint: g.lint !== false,                 // default true
+      specFreshness: g.specFreshness !== false, // default true
+    },
+  };
+  if (g.codegen) {
+    const c = g.codegen;
+    if (typeof c.contract !== 'string' || typeof c.regenerate !== 'string') {
+      throw new Error('gates.codegen requires string "contract" and "regenerate"');
+    }
+    const generated = c.generated === undefined ? [] : c.generated;
+    if (!Array.isArray(generated)) throw new Error('gates.codegen.generated must be an array');
+    out.gates.codegen = { contract: c.contract, regenerate: c.regenerate, generated };
+  }
+  return out;
+}
+
+export function loadConfig(cwd) {
+  const p = join(cwd, '.claude', 'house-standard.config.json');
+  if (!existsSync(p)) return null;
+  return normalizeConfig(JSON.parse(readFileSync(p, 'utf8')));
+}

