+// gates/drift.mjs — isolated regenerate → compare → restore. Tree-invariant.
+// Diff/restore range == config.gates.codegen.generated globs. Writes outside
+// those globs are not tracked (host keeps codegen output under _generated/).
+import { readFileSync, writeFileSync, rmSync, rmdirSync, readdirSync, statSync } from 'node:fs';
+import { join, relative, dirname } from 'node:path';
+import { ok, violation } from './result.mjs';
+import { matchesAny } from './glob.mjs';
+
+function walk(dir, base, acc) {
+  for (const name of readdirSync(dir)) {
+    if (name === '.git') continue;
+    const full = join(dir, name);
+    if (statSync(full).isDirectory()) walk(full, base, acc);
+    else acc.push(relative(base, full).split('\\').join('/'));
+  }
+  return acc;
+}
+
+// Snapshot the set of directories (POSIX-relative) that exist before regen, so
+// restore can tell which dirs regen newly created and prune only those.
+function listDirs(dir, base, acc) {
+  for (const name of readdirSync(dir)) {
+    if (name === '.git') continue;
+    const full = join(dir, name);
+    if (statSync(full).isDirectory()) {
+      acc.add(relative(base, full).split('\\').join('/'));
+      listDirs(full, base, acc);
+    }
+  }
+  return acc;
+}
+
+// After removing a regen-added file, walk its ancestor dirs upward and rmdir any
+// that are now empty AND did not exist before regen — leaving the tree exactly
+// as it was. Pre-existing dirs (in beforeDirs) are never removed.
+function pruneEmptyDirs(cwd, fileRel, beforeDirs) {
+  let dir = dirname(fileRel);
+  while (dir && dir !== '.' && !beforeDirs.has(dir)) {
+    const abs = join(cwd, dir);
+    try {
+      if (readdirSync(abs).length > 0) break; // not empty — keep
+      rmdirSync(abs);
+    } catch {
+      break; // already gone or unreadable — stop
+    }
+    dir = dirname(dir);
+  }
+}
+
+export function collectGenerated(cwd, globs) {
+  const map = new Map();
+  for (const rel of walk(cwd, cwd, [])) {
+    if (matchesAny(rel, globs)) map.set(rel, readFileSync(join(cwd, rel)));
+  }
+  return map;
+}
+
+function drifted(before, after) {
+  const keys = new Set([...before.keys(), ...after.keys()]);
+  for (const k of keys) {
+    const b = before.get(k);
+    const a = after.get(k);
+    if (!b || !a || !b.equals(a)) return true;
+  }
+  return false;
+}
+
+function restore(cwd, before, after, beforeDirs) {
+  for (const [rel, buf] of before) writeFileSync(join(cwd, rel), buf);
+  for (const rel of after.keys()) {
+    if (!before.has(rel)) {
+      rmSync(join(cwd, rel), { force: true });
+      pruneEmptyDirs(cwd, rel, beforeDirs);
+    }
+  }
+}
+
+export function checkDrift({ config, runner, cwd }) {
+  const cg = config.gates.codegen;
+  if (!cg || !cg.generated || cg.generated.length === 0) return ok();
+  const before = collectGenerated(cwd, cg.generated);
+  const beforeDirs = listDirs(cwd, cwd, new Set());
+  try {
+    const res = runner.make(cg.regenerate);
+    if (!res.toolPresent || res.timedOut) return ok();
+    const after = collectGenerated(cwd, cg.generated);
+    if (drifted(before, after)) {
+      return violation(`생성물이 계약과 어긋남 — \`make ${cg.regenerate}\` 후 커밋하세요 (SoT: ${cg.contract}).`);
+    }
+    return ok();
+  } finally {
+    // Always restore the tree to its pre-check state, even if regen/compare
+    // threw — recompute the current generated set so files regen newly added
+    // are deleted, and prune any now-empty dirs regen created. This is what
+    // makes the "tree-invariant" guarantee hold off the happy path.
+    restore(cwd, before, collectGenerated(cwd, cg.generated), beforeDirs);
+  }
+}

