+// gates/glob.mjs — minimal glob matcher (**, *, ?). zero-dep.
+// ** = any incl. '/'; **/ = zero-or-more dirs; * = any except '/'; ? = one non-'/'.
+
+function toRegExp(glob) {
+  let re = '';
+  let i = 0;
+  while (i < glob.length) {
+    const c = glob[i];
+    if (c === '*' && glob[i + 1] === '*') {
+      if (glob[i + 2] === '/') { re += '(?:.*/)?'; i += 3; } // **/ → zero+ dirs
+      else { re += '.*'; i += 2; }                            // ** → anything
+    } else if (c === '*') {
+      re += '[^/]*'; i += 1;
+    } else if (c === '?') {
+      re += '[^/]'; i += 1;
+    } else {
+      re += c.replace(/[.+^${}()|[\]\\]/g, '\\$&'); i += 1;
+    }
+  }
+  return new RegExp('^' + re + '$');
+}
+
+export function matches(relPath, glob) {
+  const p = String(relPath).split('\\').join('/');
+  return toRegExp(glob).test(p);
+}
+
+export function matchesAny(relPath, globs) {
+  return (globs || []).some((g) => matches(relPath, g));
+}

