+// gates/lint.mjs — per-file lint via `make lint-file FILE=<path>`. Graceful.
+import { ok, violation } from './result.mjs';
+
+export function checkLint({ config, runner, file }) {
+  if (config.gates.lint === false) return ok();
+  const res = runner.make('lint-file', { FILE: file });
+  if (!res.toolPresent || res.timedOut) return ok();
+  if (res.code === 0) return ok();
+  return violation(res.stderr || res.stdout || `lint failed: ${file}`);
+}

