+// gates/paths.mjs — normalize an edited path to a POSIX repo-relative path and
+// report whether it lies within the project root. Files outside the project are
+// not governed by this project's house-standard config, so hooks no-op on them.
+import { relative, isAbsolute } from 'node:path';
+
+export function toRepoRelative(cwd, filePath) {
+  const rel = relative(cwd, filePath).split('\\').join('/');
+  const within = rel !== '' && rel !== '..' && !rel.startsWith('../') && !isAbsolute(rel);
+  return { rel, within };
+}

