+// gates/result.mjs — Result type, level algebra, and hook-output mapping.
+// Pure: emit() returns a descriptor; hook entries perform the IO.
+
+export function ok() {
+  return { level: 'ok', messages: [] };
+}
+
+export function violation(msg) {
+  return { level: 'violation', messages: [msg] };
+}
+
+export function advisory(msg) {
+  return { level: 'advisory', messages: [msg] };
+}
+
+const RANK = { ok: 0, advisory: 1, violation: 2 };
+
+export function merge(results) {
+  let level = 'ok';
+  const messages = [];
+  for (const r of results) {
+    if (RANK[r.level] > RANK[level]) level = r.level;
+    for (const m of r.messages) messages.push(m);
+  }
+  return { level, messages };
+}
+
+export function emit(result, { event }) {
+  if (result.level === 'violation') {
+    return { code: 2, stdout: '', stderr: result.messages.join('\n') + '\n' };
+  }
+  if (result.level === 'advisory' && event === 'PostToolUse') {
+    const payload = {
+      hookSpecificOutput: {
+        hookEventName: 'PostToolUse',
+        additionalContext: result.messages.join('\n'),
+      },
+    };
+    return { code: 0, stdout: JSON.stringify(payload) + '\n', stderr: '' };
+  }
+  return { code: 0, stdout: '', stderr: '' };
+}

