+// gates/run.mjs — injectable command runner. Distinguishes tool/target absent
+// (graceful) from genuine non-zero exit (violation) via stderr pattern, not code.
+import { spawnSync } from 'node:child_process';
+
+// Target-absent patterns emitted by `make` itself (GNU + BSD). A missing
+// `make` binary is already caught via ENOENT, so we deliberately do NOT treat
+// a generic "No such file or directory" as tool-absent — that string can come
+// from a real tool failure (e.g. a linter on a missing input) and must surface
+// as a violation, not a graceful pass.
+const ABSENT_TARGET = /No rule to make target|don't know how to make/;
+
+export function classify(r) {
+  if (r.error && r.error.code === 'ENOENT') {
+    return { ran: false, code: null, stdout: '', stderr: '', toolPresent: false, timedOut: false };
+  }
+  const stdout = r.stdout == null ? '' : r.stdout.toString();
+  const stderr = r.stderr == null ? '' : r.stderr.toString();
+  if ((r.error && r.error.code === 'ETIMEDOUT') || r.signal === 'SIGTERM') {
+    return { ran: false, code: null, stdout, stderr, toolPresent: true, timedOut: true };
+  }
+  if (ABSENT_TARGET.test(stderr)) {
+    return { ran: true, code: r.status, stdout, stderr, toolPresent: false, timedOut: false };
+  }
+  return { ran: true, code: r.status, stdout, stderr, toolPresent: true, timedOut: false };
+}
+
+export function makeRunner({ cwd, timeoutMs = 60000 }) {
+  function run(argv) {
+    const [cmd, ...rest] = argv;
+    return classify(spawnSync(cmd, rest, { cwd, timeout: timeoutMs }));
+  }
+  function make(target, vars = {}) {
+    const kv = Object.entries(vars).map(([k, v]) => `${k}=${v}`);
+    return run(['make', target, ...kv]);
+  }
+  return { run, make };
+}

