+// gates/spec-freshness.mjs — advisory nudge on behavior-source edits. Pure.
+import { ok, advisory } from './result.mjs';
+
+export function isBehaviorSource(file, paths) {
+  const f = String(file).split('\\').join('/');
+  if (f.startsWith('docs/')) return false;
+  if (f.startsWith('tests/') || f.includes('/tests/')) return false;
+  return f.startsWith(paths.backend + '/') || f.startsWith(paths.frontend + '/');
+}
+
+export function checkSpecFreshness({ config, file }) {
+  if (config.gates.specFreshness === false) return ok();
+  if (!isBehaviorSource(file, config.paths)) return ok();
+  return advisory('코드 변경 — docs/spec 신선도를 확인하세요 (수정/스킵/질문 중 판단).');
+}

