+// hooks/post-tool-use.mjs — per-file lint + drift + spec-freshness. Fail-open.
+import { readFileSync } from 'node:fs';
+import { resolve } from 'node:path';
+import { fileURLToPath } from 'node:url';
+import { loadConfig } from '../gates/config.mjs';
+import { toRepoRelative } from '../gates/paths.mjs';
+import { makeRunner } from '../gates/run.mjs';
+import { checkLint } from '../gates/lint.mjs';
+import { checkDrift } from '../gates/drift.mjs';
+import { checkSpecFreshness } from '../gates/spec-freshness.mjs';
+import { merge, emit } from '../gates/result.mjs';
+
+export function main() {
+  let input;
+  try {
+    input = JSON.parse(readFileSync(0, 'utf8'));
+  } catch {
+    process.exit(0);
+  }
+  const cwd = input.cwd || process.cwd();
+  const filePath = input.tool_input && input.tool_input.file_path;
+  if (!filePath) process.exit(0);
+  const config = loadConfig(cwd);
+  if (!config) process.exit(0);
+  const { rel, within } = toRepoRelative(cwd, filePath);
+  if (!within) process.exit(0); // outside project → not governed by this config
+  const runner = makeRunner({ cwd });
+  const results = [checkLint({ config, runner, file: rel })];
+  const cg = config.gates.codegen;
+  if (cg && rel === cg.contract) results.push(checkDrift({ config, runner, cwd }));
+  results.push(checkSpecFreshness({ config, file: rel }));
+  const { code, stdout, stderr } = emit(merge(results), { event: 'PostToolUse' });
+  if (stdout) process.stdout.write(stdout);
+  if (stderr) process.stderr.write(stderr);
+  process.exit(code);
+}
+
+if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
+  try {
+    main();
+  } catch (err) {
+    process.stderr.write(`house-standard post-tool-use hook error (fail-open): ${err.message}\n`);
+    process.exit(0);
+  }
+}

