+// hooks/pre-tool-use.mjs — block direct edits to codegen derivatives. Fail-open.
+import { readFileSync } from 'node:fs';
+import { resolve } from 'node:path';
+import { fileURLToPath } from 'node:url';
+import { loadConfig } from '../gates/config.mjs';
+import { toRepoRelative } from '../gates/paths.mjs';
+import { matchesAny } from '../gates/glob.mjs';
+import { ok, violation, emit } from '../gates/result.mjs';
+
+export function main() {
+  let input;
+  try {
+    input = JSON.parse(readFileSync(0, 'utf8'));
+  } catch {
+    process.exit(0); // unparseable stdin → no-op
+  }
+  const cwd = input.cwd || process.cwd();
+  const filePath = input.tool_input && input.tool_input.file_path;
+  if (!filePath) process.exit(0);
+  const config = loadConfig(cwd);
+  if (!config) process.exit(0);
+  const { rel, within } = toRepoRelative(cwd, filePath);
+  if (!within) process.exit(0); // outside project → not governed by this config
+  const cg = config.gates.codegen;
+  let result = ok();
+  if (cg && matchesAny(rel, cg.generated)) {
+    result = violation(
+      `${rel} 는 codegen 산출물입니다 (SoT: ${cg.contract}). 직접 편집 금지 — 계약을 고치고 \`make ${cg.regenerate}\`.`,
+    );
+  }
+  const { code, stdout, stderr } = emit(result, { event: 'PreToolUse' });
+  if (stdout) process.stdout.write(stdout);
+  if (stderr) process.stderr.write(stderr);
+  process.exit(code);
+}
+
+if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
+  try {
+    main();
+  } catch (err) {
+    process.stderr.write(`house-standard pre-tool-use hook error (fail-open): ${err.message}\n`);
+    process.exit(0);
+  }
+}

