+// scaffold/lint-manifest.mjs — verify templates/ <-> manifest.json are 1:1.
+import { readFileSync, readdirSync, statSync } from 'node:fs';
+import { join, dirname, relative } from 'node:path';
+import { fileURLToPath } from 'node:url';
+
+function walk(dir, base = dir, acc = []) {
+  for (const name of readdirSync(dir)) {
+    const full = join(dir, name);
+    if (statSync(full).isDirectory()) walk(full, base, acc);
+    else acc.push(relative(base, full).split('\\').join('/'));
+  }
+  return acc;
+}
+
+export const SETUP_OWNED = ['core/house-standard.config.json.tmpl'];
+
+export function lintManifest({ templatesDir, manifest, owned = [] }) {
+  const onDisk = walk(templatesDir);
+  const nonTmpl = onDisk.filter((f) => !f.endsWith('.tmpl')).sort();
+  const allTmpl = onDisk.filter((f) => f.endsWith('.tmpl'));
+  const ownedSet = new Set(owned);
+
+  const srcs = manifest.map((e) => e.src);
+  const seen = new Set();
+  const duplicates = [];
+  for (const s of srcs) {
+    if (seen.has(s)) duplicates.push(s);
+    seen.add(s);
+  }
+
+  const tmplSet = new Set(allTmpl);
+  const orphans = allTmpl.filter((f) => !ownedSet.has(f) && !seen.has(f)).sort();
+  const missing = srcs.filter((s) => !tmplSet.has(s)).sort();
+  return { orphans, missing, nonTmpl, duplicates: [...new Set(duplicates)].sort() };
+}
+
+const __dirname = dirname(fileURLToPath(import.meta.url));
+
+export function runCli() {
+  const templatesDir = join(__dirname, 'templates');
+  const manifest = JSON.parse(readFileSync(join(__dirname, 'manifest.json'), 'utf8'));
+  const r = lintManifest({ templatesDir, manifest, owned: SETUP_OWNED });
+  const problems = [];
+  if (r.nonTmpl.length) problems.push(`Non-.tmpl files under templates/: ${r.nonTmpl.join(', ')}`);
+  if (r.orphans.length) problems.push(`Templates not in manifest (orphans): ${r.orphans.join(', ')}`);
+  if (r.missing.length) problems.push(`Manifest srcs missing on disk: ${r.missing.join(', ')}`);
+  if (r.duplicates.length) problems.push(`Duplicate manifest srcs: ${r.duplicates.join(', ')}`);
+  if (problems.length) {
+    process.stderr.write(problems.join('\n') + '\n');
+    process.exit(2);
+  }
+  process.stdout.write(`manifest ok: ${manifest.length} entries, all templates accounted for\n`);
+}
+
+if (process.argv[1] && process.argv[1].endsWith('lint-manifest.mjs')) runCli();

