+// scaffold/scaffold.mjs — deterministic house-standard scaffolder engine.
+// Pure functions + a CLI entry. No randomness, no timestamps: output is a
+// pure function of (answers, manifest, templates).
+
+import { readFileSync, writeFileSync, mkdirSync, existsSync, readdirSync } from 'node:fs';
+import { join, dirname, resolve } from 'node:path';
+import { fileURLToPath } from 'node:url';
+
+export function slugifyPkgName(name) {
+  let s = String(name)
+    .trim()
+    .toLowerCase()
+    .replace(/[^a-z0-9]+/g, '_')
+    .replace(/^_+|_+$/g, '');
+  if (s === '') throw new Error('projectName produces an empty package name');
+  if (/^[0-9]/.test(s)) s = '_' + s;
+  return s;
+}
+
+export function deriveTokens(answers) {
+  if (!answers || !answers.projectName) {
+    throw new Error('answers.projectName is required');
+  }
+  const fe = answers.frontend === true;
+  const mods = answers.modules || {};
+  const paths = answers.paths || {};
+  return {
+    PROJECT_NAME: answers.projectName,
+    PKG_NAME: slugifyPkgName(answers.projectName),
+    BE_PATH: paths.backend || 'backend',
+    FE_PATH: paths.frontend || 'frontend',
+    STANDARD_VERSION: answers.standardVersion || '0.0.0',
+    FRONTEND: fe ? 'true' : 'false',
+    MODULE_FRONTEND_DESIGN: fe && mods.frontend_design ? 'true' : 'false',
+    MODULE_CODEX_REVIEW: mods.codex_review ? 'true' : 'false',
+  };
+}
+
+export function resolveGates(answers) {
+  const gates = new Set(['core']);
+  if (answers.backend !== false) gates.add('be'); // default on (v1)
+  const fe = answers.frontend === true;
+  if (fe) gates.add('fe');
+  const mods = answers.modules || {};
+  if (fe && mods.frontend_design) gates.add('module:frontend_design');
+  if (mods.codex_review) gates.add('module:codex_review');
+  return gates;
+}
+
+export function substituteTokens(content, tokens) {
+  return content.replace(/\{\{([A-Z0-9_]+)\}\}/g, (_m, key) => {
+    if (!(key in tokens)) throw new Error(`Unknown token {{${key}}}`);
+    return tokens[key];
+  });
+}
+
+export function selectEntries(manifest, gates) {
+  return manifest.filter((e) => gates.has(e.gate));
+}
+
+export function computeOutputs(entries, tokens) {
+  return entries.map((e) => ({
+    src: e.src,
+    dest: substituteTokens(e.dest, tokens),
+    exec: e.exec === true,
+  }));
+}
+
+const ALLOWED_PREEXISTING = ['.git', 'README.md'];
+
+export function checkPreconditions(targetDir, { allowed = ALLOWED_PREEXISTING } = {}) {
+  const entries = readdirSync(targetDir);
+  const offending = entries.filter((e) => !allowed.includes(e));
+  if (offending.length > 0) {
+    throw new Error(
+      `Target directory not empty (allowed: ${allowed.join(', ')}). Found: ${offending.join(', ')}`,
+    );
+  }
+}
+
+export function planConflicts(outputs, targetDir) {
+  return outputs.map((o) => o.dest).filter((dest) => existsSync(join(targetDir, dest)));
+}
+
+export function writeAll(outputs, { templatesDir, targetDir, tokens }) {
+  for (const o of outputs) {
+    const raw = readFileSync(join(templatesDir, o.src), 'utf8');
+    const content = substituteTokens(raw, tokens);
+    const destPath = join(targetDir, o.dest);
+    mkdirSync(dirname(destPath), { recursive: true });
+    writeFileSync(destPath, content, o.exec ? { mode: 0o755 } : undefined);
+  }
+}
+
+export function scaffold(answers, { templatesDir, manifestPath, targetDir }) {
+  const manifest = JSON.parse(readFileSync(manifestPath, 'utf8'));
+  const tokens = deriveTokens(answers);
+  const gates = resolveGates(answers);
+  const outputs = computeOutputs(selectEntries(manifest, gates), tokens);
+  checkPreconditions(targetDir);
+  const conflicts = planConflicts(outputs, targetDir);
+  if (conflicts.length) {
+    throw new Error(`Refusing to write; existing files: ${conflicts.join(', ')}`);
+  }
+  writeAll(outputs, { templatesDir, targetDir, tokens });
+  return { written: outputs.map((o) => o.dest) };
+}
+
+// ---- CLI ----
+const __dirname = dirname(fileURLToPath(import.meta.url));
+
+function parseArgs(argv) {
+  const out = {};
+  for (let i = 0; i < argv.length; i++) {
+    const a = argv[i];
+    if (a.startsWith('--')) out[a.slice(2)] = argv[++i];
+  }
+  return out;
