+  for (const f of res.written.sort()) process.stdout.write(`  ${f}\n`);
+}
+
+if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
+  try {
+    main();
+  } catch (err) {
+    process.stderr.write(`init scaffolder error: ${err.message}\n`);
+    process.exit(1);
+  }
+}

