+// scaffold/setup.mjs — sole owner of .claude/house-standard.config.json.
+// Two modes: create (--from-answers, used by /init) and patch (--patch, used by /setup).
+// Deterministic; depends on scaffold.mjs one-directionally (token derivation).
+
+import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
+import { join, dirname, resolve } from 'node:path';
+import { fileURLToPath } from 'node:url';
+import { deriveTokens, substituteTokens } from './scaffold.mjs';
+
+const CONFIG_REL = '.claude/house-standard.config.json';
+const CONFIG_TEMPLATE = 'core/house-standard.config.json.tmpl';
+
+// /setup's entire editable surface: dotted path -> validator.
+const SWITCHES = {
+  'gates.lint': isBool,
+  'gates.specFreshness': isBool,
+  'gates.codegen.contract': isNonEmptyString,
+  'gates.codegen.regenerate': isNonEmptyString,
+  'gates.codegen.generated': isNonEmptyStringArray,
+};
+const TYPE_DESC = {
+  'gates.lint': 'a boolean',
+  'gates.specFreshness': 'a boolean',
+  'gates.codegen.contract': 'a non-empty string',
+  'gates.codegen.regenerate': 'a non-empty string',
+  'gates.codegen.generated': 'a non-empty array of non-empty strings',
+};
+
+function isBool(v) { return typeof v === 'boolean'; }
+function isNonEmptyString(v) { return typeof v === 'string' && v.length > 0; }
+function isNonEmptyStringArray(v) {
+  return Array.isArray(v) && v.length > 0 && v.every((x) => typeof x === 'string' && x.length > 0);
+}
+
+export function serializeConfig(config) {
+  return JSON.stringify(config, null, 2) + '\n';
+}
+
+export function configFromAnswers(answers, { templatesDir }) {
+  const raw = readFileSync(join(templatesDir, CONFIG_TEMPLATE), 'utf8');
+  return JSON.parse(substituteTokens(raw, deriveTokens(answers)));
+}
+
+export function readConfig(targetDir) {
+  const path = join(targetDir, CONFIG_REL);
+  if (!existsSync(path)) throw new Error(`no ${CONFIG_REL} at ${targetDir} — run /init first`);
+  const text = readFileSync(path, 'utf8');
+  try {
+    return JSON.parse(text);
+  } catch (err) {
+    throw new Error(`${CONFIG_REL} is not valid JSON: ${err.message}`);
+  }
+}
+
+export function writeConfig(targetDir, config) {
+  const path = join(targetDir, CONFIG_REL);
+  mkdirSync(dirname(path), { recursive: true });
+  writeFileSync(path, serializeConfig(config));
+}
+
+export function writeConfigFromAnswers(answers, { templatesDir, targetDir }) {
+  writeConfig(targetDir, configFromAnswers(answers, { templatesDir }));
+}
+
+// Collect [dottedPath, value] leaves from a patch object (arrays are leaves).
+function leafPaths(obj, prefix = '') {
+  const out = [];
+  for (const [k, v] of Object.entries(obj)) {
+    const path = prefix ? `${prefix}.${k}` : k;
+    if (v !== null && typeof v === 'object' && !Array.isArray(v)) out.push(...leafPaths(v, path));
+    else out.push([path, v]);
+  }
+  return out;
+}
+
+function setPath(obj, dotted, value) {
+  const keys = dotted.split('.');
+  let o = obj;
+  for (let i = 0; i < keys.length - 1; i++) {
+    if (o[keys[i]] === null || typeof o[keys[i]] !== 'object') o[keys[i]] = {};
+    o = o[keys[i]];
+  }
+  o[keys[keys.length - 1]] = value;
+}
+
+export function applyPatch(config, patch) {
+  const leaves = leafPaths(patch);
+  if (leaves.length === 0) {
+    throw new Error('patch contains no runtime switch to set (gates.lint, gates.specFreshness, gates.codegen.*)');
+  }
+  const outOfScope = [];
+  const badType = [];
+  for (const [path, value] of leaves) {
+    if (!(path in SWITCHES)) { outOfScope.push(path); continue; }
+    if (!SWITCHES[path](value)) badType.push(`${path} must be ${TYPE_DESC[path]}`);
+  }
+  if (outOfScope.length) {
+    throw new Error(
+      `out of scope for /setup: ${outOfScope.join(', ')} — /setup edits runtime switches only ` +
+      `(gates.lint, gates.specFreshness, gates.codegen.*); ` +
+      `changing paths/projectName/frontend/modules needs /upgrade`,
+    );
+  }
+  if (badType.length) throw new Error(`invalid value(s): ${badType.join('; ')}`);
+  const next = JSON.parse(JSON.stringify(config));
+  for (const [path, value] of leaves) setPath(next, path, value);
+  return next;
+}
+
+// ---- CLI ----
+const __dirname = dirname(fileURLToPath(import.meta.url));
+
+function parseArgs(argv) {
+  const out = {};
+  for (let i = 0; i < argv.length; i++) {
+    const a = argv[i];
+    if (a.startsWith('--')) out[a.slice(2)] = argv[++i];
+  }
+  return out;
+}
+
+function resolveVersion() {
+  try {
+    const pj = JSON.parse(readFileSync(join(__dirname, '..', '.claude-plugin', 'plugin.json'), 'utf8'));
+    return pj.version || '0.0.0';
+  } catch {
+    return '0.0.0';
+  }
+}
+
+export function main(argv = process.argv.slice(2)) {
+  const args = parseArgs(argv);
+  const templatesDir = args.templates ? resolve(args.templates) : join(__dirname, 'templates');
+  const targetDir = resolve(args.target || process.cwd());
+  const hasFrom = args['from-answers'] != null;
+  const hasPatch = args.patch != null;
+  if (hasFrom === hasPatch) {
+    throw new Error('provide exactly one of --from-answers <json> or --patch <json>');
+  }
+  if (hasFrom) {
+    const answers = JSON.parse(args['from-answers']);
+    if (!answers.standardVersion) answers.standardVersion = args.version || resolveVersion();
+    writeConfigFromAnswers(answers, { templatesDir, targetDir });
+    process.stdout.write(`Wrote ${CONFIG_REL} (from answers) into ${targetDir}\n`);
+    return;
+  }
+  const next = applyPatch(readConfig(targetDir), JSON.parse(args.patch));
+  writeConfig(targetDir, next);
+  process.stdout.write(`Updated ${CONFIG_REL} in ${targetDir}\n`);
+}
+
+if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
+  try {
+    main();
+  } catch (err) {
+    process.stderr.write(`setup error: ${err.message}\n`);
+    process.exit(1);
+  }
+}

