+// tests/gates/drift.test.mjs
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, existsSync, rmSync } from 'node:fs';
+import { tmpdir } from 'node:os';
+import { join } from 'node:path';
+import { checkDrift } from '../../gates/drift.mjs';
+
+function project(files) {
+  const d = mkdtempSync(join(tmpdir(), 'drift-'));
+  for (const [rel, content] of Object.entries(files)) {
+    const p = join(d, rel);
+    mkdirSync(join(p, '..'), { recursive: true });
+    writeFileSync(p, content);
+  }
+  return d;
+}
+
+const config = (generated = ['**/_generated/**']) => ({
+  paths: { backend: 'backend', frontend: 'frontend' },
+  gates: { lint: true, specFreshness: true, codegen: { contract: 'openapi.json', regenerate: 'gen', generated } },
+});
+
+test('checkDrift: dormant when generated empty (runner untouched)', () => {
+  const d = project({ 'openapi.json': '{}' });
+  const r = checkDrift({ config: config([]), runner: { make: () => { throw new Error('no'); } }, cwd: d });
+  assert.equal(r.level, 'ok');
+});
+
+test('checkDrift: codegen tool absent → ok (graceful)', () => {
+  const d = project({ 'backend/_generated/m.py': 'A' });
+  const r = checkDrift({ config: config(), runner: { make: () => ({ toolPresent: false, timedOut: false }) }, cwd: d });
+  assert.equal(r.level, 'ok');
+});
+
+test('checkDrift: regen produces identical bytes → ok, tree intact', () => {
+  const d = project({ 'backend/_generated/m.py': 'SAME' });
+  const runner = { make: () => { writeFileSync(join(d, 'backend/_generated/m.py'), 'SAME'); return { toolPresent: true, timedOut: false, code: 0 }; } };
+  assert.equal(checkDrift({ config: config(), runner, cwd: d }).level, 'ok');
+  assert.equal(readFileSync(join(d, 'backend/_generated/m.py'), 'utf8'), 'SAME');
+});
+
+test('checkDrift: regen changes content → violation, original bytes restored', () => {
+  const d = project({ 'backend/_generated/m.py': 'OLD' });
+  const runner = { make: () => { writeFileSync(join(d, 'backend/_generated/m.py'), 'NEW'); return { toolPresent: true, timedOut: false }; } };
+  assert.equal(checkDrift({ config: config(), runner, cwd: d }).level, 'violation');
+  assert.equal(readFileSync(join(d, 'backend/_generated/m.py'), 'utf8'), 'OLD');
+});
+
+test('checkDrift: regen adds a file → violation, added file removed on restore', () => {
+  const d = project({ 'backend/_generated/m.py': 'A' });
+  const runner = { make: () => { writeFileSync(join(d, 'backend/_generated/extra.py'), 'X'); return { toolPresent: true, timedOut: false }; } };
+  assert.equal(checkDrift({ config: config(), runner, cwd: d }).level, 'violation');
+  assert.equal(existsSync(join(d, 'backend/_generated/extra.py')), false);
+});
+
+test('checkDrift: regen deletes a file → violation, deleted file restored', () => {
+  const d = project({ 'backend/_generated/m.py': 'A', 'backend/_generated/n.py': 'B' });
+  const runner = { make: () => { rmSync(join(d, 'backend/_generated/n.py')); return { toolPresent: true, timedOut: false }; } };
+  assert.equal(checkDrift({ config: config(), runner, cwd: d }).level, 'violation');
+  assert.equal(readFileSync(join(d, 'backend/_generated/n.py'), 'utf8'), 'B');
+});
+
+test('checkDrift: regen creates file in a NEW subdir → restore prunes the now-empty subdir', () => {
+  const d = project({ 'backend/_generated/m.py': 'A' });
+  const runner = { make: () => {
+    mkdirSync(join(d, 'backend/_generated/sub'), { recursive: true });
+    writeFileSync(join(d, 'backend/_generated/sub/new.py'), 'X');
+    return { toolPresent: true, timedOut: false };
+  } };
+  assert.equal(checkDrift({ config: config(), runner, cwd: d }).level, 'violation');
+  assert.equal(existsSync(join(d, 'backend/_generated/sub/new.py')), false);
+  assert.equal(existsSync(join(d, 'backend/_generated/sub')), false); // empty dir pruned
+  assert.equal(existsSync(join(d, 'backend/_generated')), true);      // pre-existing dir kept
+  assert.equal(readFileSync(join(d, 'backend/_generated/m.py'), 'utf8'), 'A');
+});
+
+test('checkDrift: runner throws after mutating → tree still restored, error propagates', () => {
+  const d = project({ 'backend/_generated/m.py': 'ORIG' });
+  const runner = { make: () => { writeFileSync(join(d, 'backend/_generated/m.py'), 'CORRUPT'); throw new Error('regen blew up'); } };
+  assert.throws(() => checkDrift({ config: config(), runner, cwd: d }), /regen blew up/);
+  assert.equal(readFileSync(join(d, 'backend/_generated/m.py'), 'utf8'), 'ORIG');
+});

