+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { mkdtempSync, readFileSync, readdirSync, statSync } from 'node:fs';
+import { tmpdir } from 'node:os';
+import { join, dirname, relative } from 'node:path';
+import { fileURLToPath } from 'node:url';
+import { runInit } from './init-output.mjs';
+import { PROFILES } from './profiles.mjs';
+
+const __dirname = dirname(fileURLToPath(import.meta.url));
+const templatesDir = join(__dirname, '..', 'scaffold', 'templates');
+const manifestPath = join(__dirname, '..', 'scaffold', 'manifest.json');
+
+function walk(dir, base = dir, acc = []) {
+  for (const name of readdirSync(dir)) {
+    const full = join(dir, name);
+    if (statSync(full).isDirectory()) walk(full, base, acc);
+    else acc.push(relative(base, full).split('\\').join('/'));
+  }
+  return acc.sort();
+}
+
+for (const [name, answers] of Object.entries(PROFILES)) {
+  test(`golden: ${name} matches committed snapshot byte-for-byte`, () => {
+    const goldenDir = join(__dirname, 'golden', name);
+    const target = mkdtempSync(join(tmpdir(), `golden-${name}-`));
+    runInit(answers, { templatesDir, manifestPath, targetDir: target });
+
+    const expected = walk(goldenDir);
+    const actual = walk(target);
+    assert.deepEqual(actual, expected, 'file set differs from golden — run `make golden-update`');
+
+    for (const rel of expected) {
+      const e = readFileSync(join(goldenDir, rel));
+      const a = readFileSync(join(target, rel));
+      assert.ok(e.equals(a), `content differs: ${rel} — run \`make golden-update\``);
+    }
+  });
+}
